contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newBetLimit, uint256 betAmount) public payable {
        require(address(this).balance >= betAmount);
        uint256 betLimitBefore = c.currentBetLimit();

        // The contract starts closed, so wager() must revert before it is opened.
        bool revertedWhileClosed;
        try c.wager{value: betAmount}() {
            revertedWhileClosed = false;
        } catch {
            revertedWhileClosed = true;
        }

        // Owner adjusts the public bet limit (safe even while closed).
        c.AdjustBetAmounts(newBetLimit);

        // Owner opens the contract to the public.
        c.OpenToThePublic();

        // Get the actual current bet limit after adjustment.
        uint256 betLimitNow = c.currentBetLimit();

        require(address(this).balance >= betLimitNow);

        // First successful wager at the adjusted limit.
        c.wager{value: betLimitNow}();

        bool playerAfter = c.hasPlayerWagered(address(this));
        uint256 betLimitAfter = c.currentBetLimit();

        assert(revertedWhileClosed && playerAfter && betLimitAfter == newBetLimit);
    }

    receive() external payable {}
}

