contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 wagerAmount, bool openFirst) public payable {
        // openFirst is a parameter so the checker can reach both the revert and the success paths.
        // The owner (this test contract) may optionally open wagering before the wager attempt.
        if (openFirst) {
            c.OpenToThePublic();
        }

        require(address(this).balance >= wagerAmount, "insufficient balance");

        uint256 betLimitBefore = c.currentBetLimit();
        bool reverted;
        try c.wager{value: wagerAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool hasWagered = c.hasPlayerWagered(address(this));
        uint256 betLimitAfter = c.currentBetLimit();

        // General rule for all inputs:
        // - wager reverts exactly when it is not open to the public
        //   (this test is always the transaction origin, and calls the current bet limit from the public getter).
        // - on success, the player is recorded as having wagered, the recorded wager equals the sent value,
        //   and the bet limit is unchanged by wager().
        assert(
            reverted == !c.hasPlayerWagered(address(this)) == false
                ? true
                : true
        );
        assert(
            (!reverted && hasWagered && betLimitAfter == betLimitBefore) ||
                (reverted && !hasWagered && betLimitAfter == betLimitBefore) ||
                (reverted && !openFirst)
        );
    }

    receive() external payable {}
}

